struct Player {
    name: String,
    level: u32,
    online: bool,
}

fn main() {
    let p = Player {
        name: String::from("Mai"),
        level: 7,
        online: true,
    };
    println!("{} is level {} (online: {})", p.name, p.level, p.online);
}

struct Counter {
    count: u32,
}

fn main() {
    let mut c = Counter { count: 0 };
    c.count += 1;
    c.count += 1;
    println!("{}", c.count);
}

#[derive(Debug)]
struct Point {
    x: i32,
    y: i32,
}

fn main() {
    let x = 4;
    let p = Point { x, y: -2 };   // x is shorthand for x: x
    println!("{:?}", p);
    println!("{:#?}", p);
    println!("x is {}, y is {}", p.x, p.y);
}

